  +  const marginTop = remToPx(m.top, rootPx);
  +  const marginBottom = remToPx(m.bottom, rootPx);
  +  const marginLeft = remToPx(m.left, rootPx);
  +  const marginRight = remToPx(m.right, rootPx);
  +
  +  // In continuous mode there is no sheet, so the "page" is the text column
  +  // the writer chose and height is irrelevant. Callers check `pagination`
  +  // before using this, but returning something coherent keeps the type honest.
  +  const pageW =
  +    setup.pagination === "continuous"
  +      ? remToPx(DOC_WIDTH_REM[layout.width], rootPx) + marginLeft + marginRight
  +      : inToPx(setup.widthIn);
  +  const pageH = inToPx(setup.heightIn);
  +
  +  // A writer can drag the margins until they meet. Never hand back a
  +  // non-positive content box: every downstream division would produce
  +  // Infinity and the engine would allocate pages until the tab died.
  +  const MIN_CONTENT = 1;
  +  return {
  +    pageH,
  +    pageW,
  +    gap: remToPx(gapRem, rootPx),
  +    marginTop,
  +    marginBottom,
  +    marginLeft,
  +    marginRight,
  +    contentH: Math.max(MIN_CONTENT, pageH - marginTop - marginBottom),
  +    contentW: Math.max(MIN_CONTENT, pageW - marginLeft - marginRight),
  +  };
  +}
  +
  +/**
  + * Reconstruct the un-paginated vertical stack from per-block measurements.
  + *
  + * Returns the top edge of each block's border box, in CSS px, relative to the
  + * top of the content area. Adjacent margins collapse — `max(mB[i], mT[i+1])`
  + * rather than the sum — because that is what the browser does and the whole
  + * point of computing this ourselves is to model the layout we are not reading.
  + *
  + * `forcedBreak` blocks are normalised to zero height and zero margins here, so
  + * that a manual page break occupies no space on the page it opens.
  + */
  +export function buildNaturalStack(metrics: readonly BlockMetric[]): number[] {
  +  const tops: number[] = new Array(metrics.length);
  +  let y = 0;
  +  for (let i = 0; i < metrics.length; i++) {
  +    const m = metrics[i];
  +    const mt = m.forcedBreak ? 0 : m.marginTop;
  +    if (i === 0) {
  +      // The container has padding, so the first block's top margin does not
  +      // collapse through it — it applies as-is.
  +      y = mt;
  +    } else {
  +      const prev = metrics[i - 1];
  +      const prevMb = prev.forcedBreak ? 0 : prev.marginBottom;
  +      const prevH = prev.forcedBreak ? 0 : prev.height;
  +      // A margin against a page break is truncated, the way CSS truncates
  +      // margins at any fragmentation boundary. Without this the first
  +      // paragraph after a manual break floats its own margin-top below the
  +      // page's content top, and the break looks mis-aligned by a line.
  +      const collapsed = prev.forcedBreak ? 0 : Math.max(prevMb, mt);
  +      y = tops[i - 1] + prevH + collapsed;
  +    }
  +    tops[i] = y;
  +  }
  +  return tops;
  +}
  +
  +/** Bottom edge of the last block's ink, relative to the content origin. */
  +function stackInkBottom(
  +  metrics: readonly BlockMetric[],
  +  tops: readonly number[],
  +  index: number,
  +): number {
  +  const m = metrics[index];
  +  return tops[index] + (m.forcedBreak ? 0 : m.height);
  +}
  +
  +/**
  + * Decide where the pages break and how tall each spacer must be.
  + *
  + * The contract, stated plainly because it is easy to lose: blocks break
  + * **atomically**. A paragraph or a table is never split across a sheet. A
  + * block taller than one page starts a fresh page and then bleeds through the
  + * gap onto the sheets below. That is the fidelity ceiling of a decoration-based
  + * engine, and it is the same ceiling every browser-based word processor has;
  + * pretending otherwise would mean splitting `<tbody>` with a `<div>`, which
  + * the HTML parser simply refuses to do.
  + */
  +export function paginate(
  +  metrics: readonly BlockMetric[],
  +  geometry: PageGeometry,
  +  options: PaginateOptions = {},
  +): PaginationResult {
  +  const { tailHeight = 0, maxPages = Number.POSITIVE_INFINITY } = options;
  +
  +  if (metrics.length === 0) {
  +    return { breaks: [], pageCount: 1 };
  +  }
  +
  +  const tops = buildNaturalStack(metrics);
  +  const { contentH, pageH, gap } = geometry;
  +  const period = pageH + gap;
  +
  +  const breaks: PageBreak[] = [];
  +  // Index of the first block on the page currently being filled, and that
  +  // page's 0-based number. `pageOf` trails `breaks` by one entry.
  +  let runStart = 0;
  +  let runPage = 0;
  +
  +  const closeRun = (nextStart: number, forced: boolean) => {
  +    // How far the ink on this page actually reaches.
  +    const inkExtent = stackInkBottom(metrics, tops, nextStart - 1) - tops[runStart];
  +    // How far the *stack* advances before the next page's first block, which
  +    // includes the margin collapsing at the boundary. The grid is defined on
  +    // this, because it is what shifts the following blocks.
  +    const used = tops[nextStart] - tops[runStart];
  +
  +    // How many sheets this run visually occupies. One, unless a single block
  +    // was taller than the page and overflowed. The loop rather than a bare
  +    // ceil() guarantees a strictly positive spacer even when the content
  +    // happens to land exactly on a sheet boundary; it terminates because each
  +    // pass adds a full `period`.
  +    let spanned = Math.max(1, Math.ceil(inkExtent / period));
  +    while (spanned * period - used < gap) spanned++;
  +
  +    const height = spanned * period - used;
  +    breaks.push({
  +      blockIndex: nextStart,
  +      pos: metrics[nextStart].pos,
  +      height,
  +      forced,
  +      page: runPage + spanned,
  +    });
  +    runStart = nextStart;
  +    runPage += spanned;
  +  };
  +
  +  for (let i = 1; i < metrics.length; i++) {
  +    if (runPage >= maxPages) break;
  +
  +    const forced = metrics[i].forcedBreak === true;
  +    // Overflow test. Measured from the first block on this page to the ink
  +    // bottom of the candidate: if the candidate's ink clears the content box,
  +    // it belongs on the next sheet. `i > runStart` is guaranteed by the loop,
  +    // so the block that opens a page can never be pushed off it — which is
  +    // what stops an oversized block from looping forever.
  +    const overflows =
  +      stackInkBottom(metrics, tops, i) - tops[runStart] > contentH;
  +
  +    if (!forced && !overflows) continue;
  +
  +    let breakAt = i;
  +    if (!forced) {
  +      // keepWithNext: a heading must not be stranded as the last block on a
  +      // page. Walk the break backwards over any run of them. Stop at
  +      // `runStart + 1` — moving further would leave the page empty, so the
  +      // constraint is dropped rather than allowed to loop.
  +      while (breakAt > runStart + 1 && metrics[breakAt - 1].keepWithNext) {
  +        breakAt--;
  +      }
  +    }
  +
  +    closeRun(breakAt, forced);
  +
  +    // A backwards keepWithNext walk can leave `i` on the new page already;
  +    // re-test it there rather than skipping it.
  +    if (breakAt < i) i = breakAt;
  +  }
  +
  +  // The final run, plus whatever the page canvas renders after the editor.
  +  const lastIndex = metrics.length - 1;
  +  const finalInk =
  +    stackInkBottom(metrics, tops, lastIndex) - tops[runStart] + tailHeight;
  +  const finalSpanned = Math.max(1, Math.ceil(finalInk / period));
  +  const pageCount = Math.min(runPage + finalSpanned, maxPages);
  +
  +  return { breaks, pageCount };
  +}
  +
  +/**
  + * Whether two break lists are identical.
  + *
  + * The engine skips its dispatch when they are. With the fixed-point property
  + * above this should never actually fire, which is exactly why it is worth
  + * keeping: it is the cheap guard that makes an infinite measure/decorate loop
  + * structurally impossible rather than merely unlikely.
  + */
  +export function sameBreaks(
  +  a: readonly PageBreak[],
  +  b: readonly PageBreak[],
  +): boolean {
  +  if (a.length !== b.length) return false;
  +  for (let i = 0; i < a.length; i++) {
  +    if (
  +      a[i].blockIndex !== b[i].blockIndex ||
  +      a[i].pos !== b[i].pos ||
  +      a[i].page !== b[i].page ||
  +      a[i].forced !== b[i].forced ||
  +      // A tolerance rather than a rounding: `Math.round` disagrees with
  +      // itself either side of a .5 boundary, which would report movement
  +      // for a fifth of a pixel of font-metric noise.
  +      Math.abs(a[i].height - b[i].height) >= SPACER_EPSILON_PX
  +    ) {
  +      return false;
  +    }
  +  }
  +  return true;
  +}
  +
  +/** Sub-pixel spacer movement below this is font-metric noise, not a relayout. */
  +export const SPACER_EPSILON_PX = 0.5;

  diff --git a/src/components/ui/color-picker.tsx b/src/components/ui/color-picker.tsx
  new file mode 100644
  index 0000000..66766a7
  --- /dev/null
  +++ b/src/components/ui/color-picker.tsx
  @@ -0,0 +1,180 @@
  +import {
  +  component$,
  +  useSignal,
  +  useVisibleTask$,
  +  $,
  +  type PropFunction,
  +} from "@builder.io/qwik";
  +import {
  +  normalizeHex,
  +  swatchesFor,
  +  type PaletteKind,
  +} from "../../utils/palette";
  +
  +const RECENT_KEY = "twyne.colors.recent";
  +const MAX_RECENT = 8;
  +
  +interface ColorPickerProps {
  +  /** Which palette to offer: prose colour, highlighter, or accent. */
  +  kind: PaletteKind;
  +  /** Currently applied colour, as a hex literal. */
  +  value?: string | null;
  +  /** Applies a colour. Always receives a normalised `#rrggbb`. */
  +  onPick$: PropFunction<(hex: string) => void>;
  +  /** Removes the colour entirely. */
  +  onClear$?: PropFunction<() => void>;
  +  /** Wording for the clear action, e.g. "No highlight". */
  +  clearLabel?: string;
  +  /** Dismisses the popover. */
  +  onClose$?: PropFunction<() => void>;
  +  title?: string;
  +}
  +
  +/** Read the recent list, tolerating anything that has been put in its place. */
  +function readRecent(): string[] {
  +  if (typeof localStorage === "undefined") return [];
  +  try {
  +    const raw = JSON.parse(localStorage.getItem(RECENT_KEY) ?? "[]");
  +    if (!Array.isArray(raw)) return [];
  +    return raw
  +      .filter((v): v is string => typeof v === "string")
  +      .map((v) => normalizeHex(v))
  +      .filter((v): v is string => v !== null)
  +      .slice(0, MAX_RECENT);
  +  } catch {
  +    return [];
  +  }
  +}
  +
  +function rememberRecent(hex: string): string[] {
  +  const next = [hex, ...readRecent().filter((h) => h !== hex)].slice(
  +    0,
  +    MAX_RECENT,
  +  );
  +  try {
  +    localStorage.setItem(RECENT_KEY, JSON.stringify(next));
  +  } catch {
  +    /* private mode, quota — a lost history is not worth an error */
  +  }
  +  return next;
  +}
  +
  +/**
  + * A colour popover: the house palette, whatever the writer used recently, and
  + * an escape hatch to any colour at all.
  + *
  + * Colours are handed back as `#rrggbb` literals, never as `var(--color-…)`.
  + * That is load-bearing rather than incidental: a mark styled with a custom
  + * property renders correctly in the app and renders as *nothing* in an
  + * exported standalone HTML file, which carries no stylesheet to resolve it.
  + * Anything that can leave the document has to be a literal colour.
  + *
  + * Anchored by the caller — it renders in flow and expects to sit inside a
  + * positioned wrapper, the same shape the layout and table popovers use.
  + */
  +export const ColorPicker = component$<ColorPickerProps>((props) => {
  +  const recent = useSignal<string[]>([]);
  +  const custom = useSignal("#c1272d");
  +
  +  // eslint-disable-next-line qwik/no-use-visible-task
  +  useVisibleTask$(() => {
  +    recent.value = readRecent();
  +    if (props.value) custom.value = normalizeHex(props.value) ?? custom.value;
  +  });
  +
  +  const pick = $((raw: string) => {
  +    const hex = normalizeHex(raw);
  +    if (!hex) return;
  +    recent.value = rememberRecent(hex);
  +    props.onPick$(hex);
  +    props.onClose$?.();
  +  });
  +
  +  const swatches = swatchesFor(props.kind);
  +  const active = props.value ? normalizeHex(props.value) : null;
  +
  +  return (
  +    <div
  +      data-color-picker
  +      class="absolute left-0 top-full mt-1 p-3 bg-[var(--color-paper)] border border-[var(--color-paper-3)] shadow-lg"
  +      style={{
  +        zIndex: "var(--z-dropdown)",
  +        borderRadius: "2px",
  +        fontFamily: "var(--font-typewriter)",
  +        width: "13rem",
  +      }}
  +      role="dialog"
  +      aria-label={props.title ?? "Choose a colour"}
  +    >
  +      <p class="dept-label mb-2">{props.title ?? "Colour"}</p>
  +
  +      <div class="flex flex-wrap gap-1.5 mb-3">
  +        {swatches.map((s) => (
  +          <button
  +            key={s.id}
  +            type="button"
  +            class="swatch"
  +            style={{ background: s.hex }}
  +            aria-pressed={active === s.hex.toLowerCase()}
  +            title={s.label}
  +            aria-label={s.label}
  +            onClick$={() => pick(s.hex)}
  +          />
  +        ))}
  +      </div>
  +
  +      {recent.value.length > 0 && (
  +        <>
  +          <p class="dept-label mb-1.5">Recent</p>
  +          <div class="flex flex-wrap gap-1.5 mb-3">
  +            {recent.value.map((hex) => (
  +              <button
  +                key={hex}
  +                type="button"
  +                class="swatch"
  +                style={{ background: hex }}
  +                aria-pressed={active === hex}
  +                title={hex}
  +                aria-label={`Recent colour ${hex}`}
  +                onClick$={() => pick(hex)}
  +              />
  +            ))}
  +          </div>
  +        </>
  +      )}
  +
  +      <label class="flex items-center gap-2 mb-3 text-[0.68rem] text-[var(--color-ink-light)]">
  +        <input
  +          type="color"
  +          class="h-6 w-8 cursor-pointer border border-[var(--color-paper-3)] bg-transparent p-0"
  +          value={custom.value}
  +          onInput$={(_, el) => {
  +            custom.value = el.value;
  +          }}
  +          aria-label="Custom colour"
  +        />
  +        <span>Custom</span>
  +        <button
  +          type="button"
  +          class="btn-paper ml-auto px-2 py-0.5 text-[0.65rem]"
  +          onClick$={() => pick(custom.value)}
  +        >
  +          Apply
  +        </button>
  +      </label>
  +
  +      {props.onClear$ && (
  +        <button
  +          type="button"
  +          class="w-full text-left text-[0.68rem] text-[var(--color-ink-muted)] hover:text-[var(--color-vermilion)]"
  +          onClick$={() => {
  +            props.onClear$?.();
  +            props.onClose$?.();
  +          }}
  +        >
  +          ✕ {props.clearLabel ?? "Remove colour"}
  +        </button>
  +      )}
  +    </div>
  +  );
  +});

  diff --git a/src/components/ui/speech-transport.tsx b/src/components/ui/speech-transport.tsx
  new file mode 100644
  index 0000000..7b440ab
  --- /dev/null
  +++ b/src/components/ui/speech-transport.tsx
  @@ -0,0 +1,178 @@
  +import {
  +  component$,
  +  useSignal,
  +  useVisibleTask$,
  +  $,
  +  type PropFunction,
  +} from "@builder.io/qwik";
  +import {
  +  seekSpeech,
  +  speechState,
  +  stopSpeech,
  +  togglePauseSpeech,
  +  type SpeechStatus,
  +} from "../../utils/speech";
  +
  +interface SpeechTransportProps {
  +  /** The id this transport owns, matched against the speech manager's. */
  +  id: string;
  +  /** Starts a reading. Called only when nothing of ours is already sounding. */
  +  onPlay$: PropFunction<() => void>;
  +  /** Label for the play control when idle. */
  +  playLabel?: string;
  +}
  +
  +function mmss(seconds: number): string {
  +  if (!Number.isFinite(seconds) || seconds <= 0) return "0:00";
  +  const m = Math.floor(seconds / 60);
  +  const s = Math.floor(seconds % 60);
  +  return `${m}:${String(s).padStart(2, "0")}`;
  +}
  +
  +/**
  + * Play / pause / stop for reading the manuscript aloud, with progress.
  + *
  + * The toolbar previously had a bare "read" button that called the speech
  + * manager and then showed nothing at all — no spinner while a paragraph was
  + * being synthesised, no indication it was playing, and, most damagingly, no
  + * error when synthesis failed. A writer with no voice provider configured
  + * pressed it and got silence, which is indistinguishable from a broken button.
  + * Everything this component adds exists to make the state visible.
  + *
  + * The controls collapse when idle: one play button, and the transport only
  + * unfolds once there is something to control.
  + */
  +export const SpeechTransport = component$<SpeechTransportProps>((props) => {
  +  const status = useSignal<SpeechStatus>("idle");
  +  const errorMessage = useSignal("");
  +  const current = useSignal(0);
  +  const total = useSignal(0);
  +
  +  // eslint-disable-next-line qwik/no-use-visible-task
  +  useVisibleTask$(({ cleanup }) => {
  +    const sync = () => {
  +      const s = speechState();
  +      if (s.id === props.id) {
  +        status.value = s.status;
  +        errorMessage.value = s.error?.message ?? "";
  +        current.value = s.currentTime;
  +        total.value = s.duration;
  +      } else if (status.value !== "idle") {
  +        // Another passage took over; this transport goes quiet.
  +        status.value = "idle";
  +        errorMessage.value = "";
  +        current.value = 0;
  +        total.value = 0;
  +      }
  +    };
  +    window.addEventListener("twyne:speech", sync);
  +    sync();
  +    cleanup(() => window.removeEventListener("twyne:speech", sync));
  +  });
  +
  +  const primary = $(() => {
  +    if (status.value === "playing" || status.value === "paused") {
  +      togglePauseSpeech();
  +      return;
  +    }
  +    props.onPlay$();
  +  });
  +
  +  const active =
  +    status.value === "playing" ||
  +    status.value === "paused" ||
  +    status.value === "loading";
  +
  +  const primaryLabel =
  +    status.value === "playing"
  +      ? "Pause reading"
  +      : status.value === "paused"
  +        ? "Resume reading"
  +        : status.value === "loading"
  +          ? "Preparing the reading — press to cancel"
  +          : (props.playLabel ?? "Read aloud");
  +
  +  return (
  +    <span class="inline-flex items-center gap-1">
  +      <button
  +        type="button"
  +        onClick$={primary}
  +        class="tool-btn"
  +        title={
  +          status.value === "error"
  +            ? errorMessage.value || "Could not read this aloud"
  +            : primaryLabel
  +        }
  +        aria-label={primaryLabel}
  +        aria-pressed={status.value === "playing"}
  +        style={{
  +          color:
  +            status.value === "error"
  +              ? "var(--color-accent-red)"
  +              : status.value === "playing" || status.value === "paused"
  +                ? "var(--color-vermilion)"
  +                : undefined,
  +        }}
  +      >
  +        {status.value === "loading"
  +          ? "◌ read"
  +          : status.value === "playing"
  +            ? "❚❚ pause"
  +            : status.value === "paused"
  +              ? "▶ resume"
  +              : "♪ read"}
  +      </button>
  +
  +      {active && (
  +        <>
  +          <button
  +            type="button"
  +            onClick$={() => stopSpeech()}
  +            class="tool-btn"
  +            title="Stop reading"
  +            aria-label="Stop reading"
  +          >
  +            ■
  +          </button>
  +          {total.value > 0 && (
  +            <label
  +              class="inline-flex items-center gap-1 text-[0.62rem] text-[var(--color-ink-muted)]"
  +              style="font-family: var(--font-typewriter);"
  +            >
  +              <span class="sr-only">Reading position</span>
  +              <input
  +                type="range"
  +                class="margin-slider"
  +                style="width: 5rem;"
  +                min={0}
  +                max={total.value}
  +                step={0.1}
  +                value={current.value}
  +                onInput$={(_, el) => seekSpeech(Number(el.value))}
  +                aria-label="Reading position"
  +              />
  +              <span class="tabular-nums">
  +                {mmss(current.value)}/{mmss(total.value)}
  +              </span>
  +            </label>
  +          )}
  +        </>
  +      )}
  +
  +      {/* The whole point of the rebuild: a failure the writer can actually
  +          see. Kept inline and terse so it does not shove the toolbar around.
  +          Falls back to generic wording rather than rendering an empty box —
  +          "something went wrong" still beats the silence this replaced. */}
  +      {status.value === "error" && (
  +        <span
  +          role="status"
  +          class="text-[0.62rem] text-[var(--color-accent-red)] max-w-[16rem] truncate"
  +          style="font-family: var(--font-typewriter);"
  +          title={errorMessage.value || "Could not read this aloud"}
  +        >
  +          {errorMessage.value || "Could not read this aloud"}
  +        </span>
  +      )}
  +    </span>
  +  );
  +});

  diff --git a/src/utils/css-units.ts b/src/utils/css-units.ts
  new file mode 100644
  index 0000000..eb8c931
  --- /dev/null
  +++ b/src/utils/css-units.ts
  @@ -0,0 +1,78 @@
  +/**
  + * Conversions between the three units the page geometry has to speak.
  + *
  + * The writer drags margins in **rem**, because that is what the editor's
  + * type scale is built on and what every stored `LayoutSettings` holds. The
  + * sheet they print on is measured in **inches**, because paper is physical.
  + * Layout happens in **CSS pixels**. Everything crosses between the three
  + * here rather than in a dozen call sites, so a change to the bridge is a
  + * change in one place.
  + *
  + * `CSS_PX_PER_IN` is fixed by the CSS spec at 96, and it is the same number
  + * Chrome's print engine uses when laying out `@page`. That is what makes
  + * screen and print agree — but only when the root font size is what we
  + * think it is, which is why the export pins `html { font-size: 16px }`
  + * while the screen deliberately does not (see `resolvePageSetup`).
  + */
  +import { CSS_PX_PER_IN } from "../types";
  +
  +/** The browser default, and the value every export is pinned to. */
  +export const DEFAULT_ROOT_FONT_PX = 16;
  +
  +/**
  + * Current root font size in CSS pixels.
  + *
  + * On the server, or if the computed value is nonsense, fall back to the
  + * browser default rather than propagating a NaN into every page height.
  + */
  +export function rootFontSize(): number {
  +  if (typeof window === "undefined" || typeof document === "undefined") {
  +    return DEFAULT_ROOT_FONT_PX;
  +  }
  +  const size = parseFloat(
  +    getComputedStyle(document.documentElement).fontSize || "16",
  +  );
  +  return Number.isFinite(size) && size > 0 ? size : DEFAULT_ROOT_FONT_PX;
  +}
  +
  +/** rem → CSS px, against an explicit root size so callers stay testable. */
  +export function remToPx(rem: number, rootPx: number = DEFAULT_ROOT_FONT_PX) {
  +  return rem * rootPx;
  +}
  +
  +/** CSS px → rem. */
  +export function pxToRem(px: number, rootPx: number = DEFAULT_ROOT_FONT_PX) {
  +  return px / rootPx;
  +}
  +
  +/** CSS px → inches. Spec-fixed, no root font size involved. */
  +export function pxToIn(px: number): number {
  +  return px / CSS_PX_PER_IN;
  +}
  +
  +/** Inches → CSS px. */
  +export function inToPx(inches: number): number {
  +  return inches * CSS_PX_PER_IN;
  +}
  +
  +/** Inches → millimetres, for the ruler's readout. */
  +export function inToMm(inches: number): number {
  +  return inches * 25.4;
  +}
  +
  +/**
  + * Format a rem margin for display in the writer's chosen unit.
  + *
  + * Used by the ruler readout, which shows both the stored value and the
  + * physical one so "3 rem" and "half an inch" stop being different languages.
  + */
  +export function formatMargin(
  +  rem: number,
  +  unit: "rem" | "in" | "mm",
  +  rootPx: number = DEFAULT_ROOT_FONT_PX,
  +): string {
  +  if (unit === "rem") return `${rem.toFixed(2)} rem`;
  +  const inches = pxToIn(remToPx(rem, rootPx));
  +  if (unit === "in") return `${inches.toFixed(2)} in`;
  +  return `${inToMm(inches).toFixed(1)} mm`;
  +}

  diff --git a/src/utils/exchange-print.test.ts b/src/utils/exchange-print.test.ts
  new file mode 100644
  index 0000000..8bf7452
  --- /dev/null
  +++ b/src/utils/exchange-print.test.ts
  @@ -0,0 +1,132 @@
  +import { describe, expect, test } from "bun:test";
  +import { exportHtml, exportPlainText, stripHtml } from "./exchange";
  +import { DEFAULT_LAYOUT, type LayoutSettings } from "../types";
  +import type { ExportPayload } from "./exchange";
  +
  +/**
  + * The print stylesheet is the only place where the writer's page settings
  + * become a physical sheet, and it had two long-standing faults: margins were
  + * applied twice, and the page-number rule was a Paged Media feature Chrome
  + * has never implemented. Both are guarded here so they cannot come back.
  + */
  +
  +function payload(overrides: Partial<ExportPayload> = {}): ExportPayload {
  +  return {
  +    title: "Specimen",
  +    html: "<p>Body text.</p>",
  +    meta: {
  +      title: "Specimen",
  +      wordCount: 2,
  +      characterCount: 10,
  +      readingTime: 1,
  +      lastEdited: Date.now(),
  +    },
  +    marginalia: [],
  +    ...overrides,
  +  } as ExportPayload;
  +}
  +
  +const layout = (over: Partial<LayoutSettings> = {}): LayoutSettings => ({
  +  ...DEFAULT_LAYOUT,
  +  ...over,
  +});
  +
  +describe("print stylesheet", () => {
  +  test("the sheet size comes from paper and orientation", () => {
  +    const html = exportHtml(
  +      payload({ layout: layout({ paper: "a4", orientation: "landscape" }) }),
  +    );
  +    expect(html).toContain("@page { size: A4 landscape;");
  +  });
  +
  +  test("Letter portrait is emitted for a default layout", () => {
  +    const html = exportHtml(payload({ layout: layout() }));
  +    expect(html).toContain("size: letter portrait");
  +  });
  +
  +  test("the dead @bottom-center rule is gone", () => {
  +    // It never rendered — Chrome implements neither the margin-box selector
  +    // nor counter(page) outside one — and its presence made the exporter
  +    // look like it produced page numbers when it never had.
  +    const html = exportHtml(payload({ layout: layout({ pageNumbers: true }) }));
  +    expect(html).not.toContain("@bottom-center");
  +    // The rule, not the word — the stylesheet comments explain why it is
  +    // absent, and that explanation is worth keeping.
  +    expect(html).not.toMatch(/content:\s*counter\(page\)/);
  +  });
  +
  +  test("body carries no margin, so page margins cannot double", () => {
  +    // @page owns the margins. Setting them on body as well stacked the two
  +    // and quietly doubled every printed margin.
  +    const html = exportHtml(payload({ layout: layout({ marginLeft: 3 }) }));
  +    expect(html).toMatch(/body\s*\{[^}]*margin:\s*0;/);
  +    expect(html).toMatch(/body\s*\{[^}]*padding:\s*0;/);
  +  });
  +
  +  test("margins are converted to inches through the fixed 96px/in", () => {
  +    // 3rem at the pinned 16px root is 48px, which is half an inch.
  +    const html = exportHtml(
  +      payload({
  +        layout: layout({
  +          marginLeft: 3,
  +          marginRight: 3,
  +          marginTop: 3,
  +          marginBottom: 3,
  +        }),
  +      }),
  +    );
  +    expect(html).toContain("margin: 0.500in 0.500in 0.500in 0.500in");
  +  });
  +
  +  test("the root font size is pinned so that conversion is exact", () => {
  +    const html = exportHtml(payload());
  +    expect(html).toMatch(/html\s*\{\s*font-size:\s*16px;\s*\}/);
  +  });
  +
  +  test("the atomic-block contract is mirrored for the printer", () => {
  +    const html = exportHtml(payload());
  +    expect(html).toContain("break-inside: avoid");
  +    expect(html).toContain("break-after: avoid");
  +    expect(html).toContain("orphans: 2");
  +  });
  +
  +  test("justification and hyphenation match the editor", () => {
  +    // The screen sets both; an export that sets neither breaks its lines
  +    // somewhere else and every page drifts.
  +    const html = exportHtml(payload());
  +    expect(html).toContain("text-align: justify");
  +    expect(html).toContain("hyphens: auto");
  +  });
  +
  +  test("a manual page break maps to break-after: page", () => {
  +    const html = exportHtml(payload());
  +    expect(html).toMatch(/\[data-page-break\][^{]*\{[^}]*break-after:\s*page/);
  +  });
  +
  +  test("continuous mode leaves the sheet size to the print dialog", () => {
  +    const html = exportHtml(
  +      payload({ layout: layout({ pagination: "continuous" }) }),
  +    );
  +    expect(html).toContain("size: auto");
  +  });
  +});
  +
  +describe("plain text", () => {
  +  test("a page break becomes a form feed", () => {
  +    const text = stripHtml(
  +      '<p>One</p><div data-type="page-break" data-page-break="true"></div><p>Two</p>',
  +    );
  +    expect(text).toContain("\f");
  +  });
  +
  +  test("the break does not silently vanish from a text export", () => {
  +    const text = exportPlainText(
  +      payload({
  +        html: '<p>One</p><div data-page-break="true"></div><p>Two</p>',
  +      }),
  +    );
  +    expect(text).toContain("\f");
  +    expect(text).toContain("One");
  +    expect(text).toContain("Two");
  +  });
  +});

  diff --git a/src/utils/form-probes.test.ts b/src/utils/form-probes.test.ts
