  +import { describe, expect, test } from "bun:test";
  +import type { DossierProbe, ProjectInterviewAnswers } from "../types";
  +import type { InterviewTurnResult } from "./ai-client";
  +import { buildFormProbeMessages, requireFormProbe } from "./form-probes";
  +
  +const answers: ProjectInterviewAnswers = {
  +  workingTitle: "The Particulars",
  +  format: "Essay",
  +  audience: "Editors",
  +  goal: "Explain the failure",
  +  tone: "Exact",
  +  constraints: "Keep the writer's answers",
  +  successSignal: "The recovery path is visible",
  +};
  +
  +const probe: DossierProbe = {
  +  id: "probe-1",
  +  kind: "choice",
  +  prompt: "Which reader needs the most convincing?",
  +  options: ["Editors", "Writers"],
  +};
  +
  +describe("buildFormProbeMessages", () => {
  +  test("includes current answers and previously collected questions", () => {
  +    const messages = buildFormProbeMessages(answers, [probe]);
  +
  +    expect(messages[1]?.text).toContain("Working title: The Particulars");
  +    expect(messages[1]?.text).toContain("Goal: Explain the failure");
  +    expect(messages.at(-2)).toEqual({
  +      author: "interviewer",
  +      text: probe.prompt,
  +    });
  +  });
  +});
  +
  +describe("requireFormProbe", () => {
  +  test("accepts a renderable typed question", () => {
  +    const result: InterviewTurnResult = {
  +      kind: "question",
  +      text: probe.prompt,
  +      probe,
  +      provider: "test",
  +      model: "test",
  +    };
  +
  +    expect(requireFormProbe(result)).toEqual({ ok: true, value: probe });
  +  });
  +
  +  test.each([
  +    ["an empty response", null],
  +    [
  +      "a prose-only question",
  +      {
  +        kind: "question",
  +        text: "Tell me more.",
  +        provider: "test",
  +        model: "test",
  +      },
  +    ],
  +    [
  +      "an unexpected synthesis",
  +      {
  +        kind: "synthesis",
  +        brief: answers,
  +        confidence: {},
  +        provider: "test",
  +        model: "test",
  +      },
  +    ],
  +  ])("turns %s into a safe, retryable error", (_label, result) => {
  +    const checked = requireFormProbe(result as InterviewTurnResult | null);
  +
  +    expect(checked.ok).toBe(false);
  +    if (checked.ok) return;
  +    expect(checked.error.code).toBe("MALFORMED_RESPONSE");
  +    expect(checked.error.recovery).toEqual({
  +      action: "retry",
  +      canRetry: true,
  +    });
  +    expect(checked.error.message).not.toContain("Tell me more");
  +  });
  +});

  diff --git a/src/utils/form-probes.ts b/src/utils/form-probes.ts
  new file mode 100644
  index 0000000..3511f0e
  --- /dev/null
  +++ b/src/utils/form-probes.ts
  @@ -0,0 +1,69 @@
  +import type { DossierProbe, ProjectInterviewAnswers } from "../types";
  +import type { InterviewMessage, InterviewTurnResult } from "./ai-client";
  +import { createAppError, successResult } from "./application-errors";
  +import type { ApplicationResult } from "../types/application-errors";
  +
  +export const FORM_PROBE_COUNT = 3;
  +
  +/**
  + * Build the form interview from the writer's current answers. Each subsequent
  + * request includes the probes already collected so the model does not ask the
  + * same question three ways.
  + */
  +export function buildFormProbeMessages(
  +  answers: ProjectInterviewAnswers,
  +  collected: DossierProbe[],
  +): InterviewMessage[] {
  +  return [
  +    {
  +      author: "interviewer",
  +      text: "Tell me about the piece — the form, the reader, the goal, the tone, the constraints, and how you'll know it landed.",
  +    },
  +    {
  +      author: "writer",
  +      text: [
  +        `Working title: ${answers.workingTitle}`,
  +        `Format: ${answers.format}`,
  +        `Audience: ${answers.audience}`,
  +        `Goal: ${answers.goal}`,
  +        `Tone: ${answers.tone}`,
  +        `Constraints: ${answers.constraints}`,
  +        `Success signal: ${answers.successSignal}`,
  +      ].join("\n"),
  +    },
  +    {
  +      author: "writer",
  +      text: "(ask me one sharp follow-up as a typed question — a choice, a scale, or a fill-in-the-blanks — about whichever of those answers is vaguest)",
  +    },
  +    ...collected.flatMap((probe) => [
  +      { author: "interviewer" as const, text: probe.prompt },
  +      { author: "writer" as const, text: "(noted — ask another)" },
  +    ]),
  +  ];
  +}
  +
  +/**
  + * The Particulars page can only render typed probes. Treat a prose-only,
  + * synthesis, or empty response as a failed response contract instead of
  + * presenting an empty page as a successful result.
  + */
  +export function requireFormProbe(
  +  result: InterviewTurnResult | null,
  +): ApplicationResult<DossierProbe> {
  +  if (result?.kind === "question" && result.probe) {
  +    return successResult(result.probe);
  +  }
  +
  +  return {
  +    ok: false,
  +    error: createAppError("MALFORMED_RESPONSE", {
  +      source: "provider",
  +      recovery: { action: "retry", canRetry: true },
  +      metadata: {
  +        feature: "interview",
  +        operation: "form-probes",
  +        kind: result?.kind ?? "empty",
  +      },
  +    }),
  +  };
  +}

  diff --git a/src/utils/html-to-markdown.test.ts b/src/utils/html-to-markdown.test.ts
  new file mode 100644
  index 0000000..c7a26ae
  --- /dev/null
  +++ b/src/utils/html-to-markdown.test.ts
  @@ -0,0 +1,259 @@
  +import { describe, expect, test } from "bun:test";
  +import { decodeEntities, htmlToMarkdown, tokenize } from "./html-to-markdown";
  +
  +/**
  + * The converter this replaces called `stripHtml` first, so every inline mark
  + * was gone before conversion began. A writer who struck a sentence through and
  + * exported to Markdown got the sentence back unmarked — which is what made
  + * strikethrough look like a feature that had never been built.
  + */
  +describe("inline marks survive", () => {
  +  test("bold, italic and strikethrough", () => {
  +    expect(htmlToMarkdown("<p><strong>bold</strong></p>")).toBe("**bold**");
  +    expect(htmlToMarkdown("<p><em>italic</em></p>")).toBe("*italic*");
  +    expect(htmlToMarkdown("<p><s>struck</s></p>")).toBe("~~struck~~");
  +  });
  +
  +  test("the tag spellings TipTap and pasted HTML both produce", () => {
  +    expect(htmlToMarkdown("<p><b>b</b> <i>i</i> <del>d</del></p>")).toBe(
  +      "**b** *i* ~~d~~",
  +    );
  +  });
  +
  +  test("highlight becomes the GFM marker", () => {
  +    expect(
  +      htmlToMarkdown('<p><mark data-color="#fbeaa8">lit</mark></p>'),
  +    ).toBe("==lit==");
  +  });
  +
  +  test("marks nest", () => {
  +    expect(
  +      htmlToMarkdown("<p><strong>bold and <em>italic</em></strong></p>"),
  +    ).toBe("**bold and *italic***");
  +  });
  +
  +  test("inline code is not escaped inside the backticks", () => {
  +    expect(htmlToMarkdown("<p><code>a*b_c</code></p>")).toBe("`a*b_c`");
  +  });
  +
  +  test("links keep their target", () => {
  +    expect(
  +      htmlToMarkdown('<p>see <a href="https://twyne.love">the site</a></p>'),
  +    ).toBe("see [the site](https://twyne.love)");
  +  });
  +
  +  test("a link with no href degrades to its text", () => {
  +    expect(htmlToMarkdown("<p><a>bare</a></p>")).toBe("bare");
  +  });
  +
  +  test("superscript survives as inline HTML", () => {
  +    // GFM has no spelling for it, and dropping the character loses meaning.
  +    expect(htmlToMarkdown("<p>x<sup>2</sup></p>")).toBe("x<sup>2</sup>");
  +  });
  +});
  +
  +describe("block structure", () => {
  +  test("headings carry their level", () => {
  +    expect(htmlToMarkdown("<h1>One</h1><h2>Two</h2><h3>Three</h3>")).toBe(
  +      "# One\n\n## Two\n\n### Three",
  +    );
  +  });
  +
  +  test("paragraphs are separated by a blank line", () => {
  +    expect(htmlToMarkdown("<p>One</p><p>Two</p>")).toBe("One\n\nTwo");
  +  });
  +
  +  test("a horizontal rule is a rule", () => {
  +    expect(htmlToMarkdown("<p>a</p><hr><p>b</p>")).toBe("a\n\n---\n\nb");
  +  });
  +
  +  test("blockquotes are prefixed", () => {
  +    expect(htmlToMarkdown("<blockquote><p>quoted</p></blockquote>")).toBe(
  +      "> quoted",
  +    );
  +  });
  +
  +  test("code blocks are fenced and their contents left alone", () => {
  +    expect(
  +      htmlToMarkdown("<pre><code>const x = *y*;</code></pre>"),
  +    ).toBe("```\nconst x = *y*;\n```");
  +  });
  +});
  +
  +describe("lists", () => {
  +  test("unordered", () => {
  +    expect(htmlToMarkdown("<ul><li>one</li><li>two</li></ul>")).toBe(
  +      "- one\n- two",
  +    );
  +  });
  +
  +  test("ordered lists number themselves", () => {
  +    expect(htmlToMarkdown("<ol><li>one</li><li>two</li></ol>")).toBe(
  +      "1. one\n2. two",
  +    );
  +  });
  +
  +  test("an ordered list honours its start attribute", () => {
  +    expect(htmlToMarkdown('<ol start="3"><li>three</li></ol>')).toBe("3. three");
  +  });
  +
  +  test("nesting indents", () => {
  +    // The case regexes cannot do, and the reason this is a tokenizer.
  +    const md = htmlToMarkdown(
  +      "<ul><li>outer<ul><li>inner</li></ul></li></ul>",
  +    );
  +    expect(md).toContain("- outer");
  +    expect(md).toContain("  - inner");
  +  });
  +
  +  test("task lists become checkboxes", () => {
  +    const md = htmlToMarkdown(
  +      '<ul data-type="taskList">' +
  +        '<li data-checked="true"><p>done</p></li>' +
  +        '<li data-checked="false"><p>todo</p></li>' +
  +        "</ul>",
  +    );
  +    expect(md).toContain("- [x] done");
  +    expect(md).toContain("- [ ] todo");
  +  });
  +
  +  test("list items keep their inline marks", () => {
  +    expect(
  +      htmlToMarkdown("<ul><li><strong>bold</strong> item</li></ul>"),
  +    ).toBe("- **bold** item");
  +  });
  +});
  +
  +describe("tables", () => {
  +  test("a table becomes a GFM pipe table", () => {
  +    const md = htmlToMarkdown(
  +      "<table><tbody>" +
  +        "<tr><th>Name</th><th>Role</th></tr>" +
  +        "<tr><td>Ada</td><td>Analyst</td></tr>" +
  +        "</tbody></table>",
  +    );
  +    expect(md).toBe(
  +      "| Name | Role |\n| --- | --- |\n| Ada | Analyst |",
  +    );
  +  });
  +
  +  test("a paragraph inside a cell does not break the row", () => {
  +    const md = htmlToMarkdown(
  +      "<table><tbody><tr><td><p>one</p></td><td><p>two</p></td></tr></tbody></table>",
  +    );
  +    expect(md).toBe("| one | two |\n| --- | --- |");
  +  });
  +
  +  test("a pipe in a cell is escaped rather than breaking the table", () => {
  +    const md = htmlToMarkdown(
  +      "<table><tbody><tr><td>a|b</td></tr></tbody></table>",
  +    );
  +    expect(md).toContain("a\\|b");
  +  });
  +
  +  test("ragged rows are padded to a rectangle", () => {
  +    const md = htmlToMarkdown(
  +      "<table><tbody><tr><td>a</td><td>b</td></tr><tr><td>c</td></tr></tbody></table>",
  +    );
  +    expect(md.split("\n")[2]).toBe("| c |  |");
  +  });
  +
  +  test("marks inside cells survive", () => {
  +    const md = htmlToMarkdown(
  +      "<table><tbody><tr><td><s>gone</s></td></tr></tbody></table>",
  +    );
  +    expect(md).toContain("~~gone~~");
  +  });
  +});
  +
  +describe("images and page breaks", () => {
  +  test("an image keeps its alt text and source", () => {
  +    expect(htmlToMarkdown('<p><img src="/a.png" alt="A plate"></p>')).toBe(
  +      "![A plate](/a.png)",
  +    );
  +  });
  +
  +  test("a base64 image is named rather than pasted", () => {
  +    // Otherwise a single inlined photograph is megabytes of noise in a file
  +    // whose whole point is being readable as text.
  +    const md = htmlToMarkdown(
  +      '<p><img src="data:image/png;base64,AAAA" alt="x"></p>',
  +    );
  +    expect(md).toBe("![x](embedded-image)");
  +    expect(md).not.toContain("base64");
  +  });
  +
  +  test("a page break is dropped rather than mistaken for a rule", () => {
  +    // `---` is a horizontal rule, which the schema has separately. Emitting
  +    // one here would put a visible line in the document that the writer
  +    // never asked for.
  +    const md = htmlToMarkdown(
  +      '<p>a</p><div data-page-break="true"></div><p>b</p>',
  +    );
  +    expect(md).toBe("a\n\nb");
  +  });
  +});
  +
  +describe("escaping and entities", () => {
  +  test("Markdown punctuation in prose is escaped", () => {
  +    expect(htmlToMarkdown("<p>a * b _ c</p>")).toBe("a \\* b \\_ c");
  +  });
  +
  +  test("entities decode", () => {
  +    expect(decodeEntities("a &amp; b &mdash; c &#39;d&#39;")).toBe(
  +      "a & b — c 'd'",
  +    );
  +  });
  +
  +  test("a doubly-encoded ampersand decodes only once", () => {
  +    // &amp; must resolve last, or &amp;lt; becomes a literal "<".
  +    expect(decodeEntities("&amp;lt;")).toBe("&lt;");
  +  });
  +
  +  test("style and script contents are dropped entirely", () => {
  +    expect(
  +      htmlToMarkdown("<style>p{color:red}</style><p>kept</p>"),
  +    ).toBe("kept");
  +  });
  +});
  +
  +describe("tokenizer", () => {
  +  test("attributes with > inside quotes do not end the tag", () => {
  +    const tokens = tokenize('<a title="a > b">x</a>');
  +    expect(tokens[0].attrs?.title).toBe("a > b");
  +  });
  +
  +  test("self-closing and void tags are marked", () => {
  +    expect(tokenize("<br>")[0].void).toBe(true);
  +    expect(tokenize("<img />")[0].void).toBe(true);
  +  });
  +
  +  test("unclosed tags do not throw", () => {
  +    expect(() => htmlToMarkdown("<p>dangling")).not.toThrow();
  +    expect(htmlToMarkdown("<p>dangling")).toBe("dangling");
  +  });
  +
  +  test("empty input is empty output", () => {
  +    expect(htmlToMarkdown("")).toBe("");
  +  });
  +});
  +
  +describe("a realistic manuscript", () => {
  +  test("everything at once round-trips into readable Markdown", () => {
  +    const html =
  +      "<h2>The Argument</h2>" +
  +      "<p>A <strong>strong</strong> claim, a <em>softer</em> one, and a " +
  +      "<s>retracted</s> one, with <a href='/notes'>a reference</a>.</p>" +
  +      "<ul><li>first</li><li>second</li></ul>" +
  +      "<blockquote><p>Someone else said it better.</p></blockquote>";
  +    const md = htmlToMarkdown(html);
  +
  +    expect(md).toContain("## The Argument");
  +    expect(md).toContain("**strong**");
  +    expect(md).toContain("*softer*");
  +    expect(md).toContain("~~retracted~~");
  +    expect(md).toContain("[a reference](/notes)");
  +    expect(md).toContain("- first");
  +    expect(md).toContain("> Someone else said it better.");
  +  });
  +});

  diff --git a/src/utils/html-to-markdown.ts b/src/utils/html-to-markdown.ts
  new file mode 100644
  index 0000000..6c227bb
  --- /dev/null
  +++ b/src/utils/html-to-markdown.ts
  @@ -0,0 +1,432 @@
  +/**
  + * HTML → Markdown for the manuscript export.
  + *
  + * The implementation this replaces called `stripHtml` on its first line and
  + * then ran regexes over the resulting plain text. Every inline mark the writer
  + * had applied — bold, italic, strikethrough, links, inline code, highlights —
  + * was gone before the conversion began, and the only structure that survived
  + * was whatever happened to look like a heading or a bullet once the tags were
  + * removed. A writer who struck a sentence through and exported to Markdown got
  + * the sentence back unmarked, which is what made strikethrough look like a
  + * feature that had never been built.
  + *
  + * Written as a small recursive tokenizer over the tag stream rather than as
  + * regex passes, because the two things regexes cannot do here are nesting
  + * (a list inside a list inside a blockquote) and context (a `<p>` inside a
  + * table cell must not become a paragraph break). No DOM: this runs under
  + * `bun test` and in the browser, and pulling in a parser for one export path
  + * is not worth the dependency.
  + */
  +
  +interface Token {
  +  kind: "open" | "close" | "text";
  +  /** Lower-cased tag name, for open/close. */
  +  name?: string;
  +  attrs?: Record<string, string>;
  +  /** Decoded text, for text tokens. */
  +  text?: string;
  +  /** Self-closing or void element. */
  +  void?: boolean;
  +}
  +
  +const VOID_TAGS = new Set([
  +  "br", "hr", "img", "input", "meta", "link", "col", "area", "base", "wbr",
  +]);
  +
  +/** Tags whose contents are dropped wholesale. */
  +const DISCARD_TAGS = new Set(["style", "script", "head", "title"]);
  +
  +export function decodeEntities(text: string): string {
  +  return text
  +    .replace(/&nbsp;/g, " ")
  +    .replace(/&lt;/g, "<")
  +    .replace(/&gt;/g, ">")
  +    .replace(/&quot;/g, '"')
  +    .replace(/&#0?39;/g, "'")
  +    .replace(/&apos;/g, "'")
  +    .replace(/&hellip;/g, "…")
  +    .replace(/&mdash;/g, "—")
  +    .replace(/&ndash;/g, "–")
  +    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
  +    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  +    // Ampersand last, or a doubly-encoded entity decodes twice.
  +    .replace(/&amp;/g, "&");
  +}
  +
  +function parseAttrs(raw: string): Record<string, string> {
  +  const attrs: Record<string, string> = {};
  +  const re = /([a-zA-Z_:][-\w:.]*)\s*(?:=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?/g;
  +  let m: RegExpExecArray | null;
  +  while ((m = re.exec(raw))) {
  +    attrs[m[1].toLowerCase()] = decodeEntities(m[2] ?? m[3] ?? m[4] ?? "");
  +  }
  +  return attrs;
  +}
  +
  +export function tokenize(html: string): Token[] {
  +  const tokens: Token[] = [];
  +  const re = /<(\/)?([a-zA-Z][-\w:]*)((?:"[^"]*"|'[^']*'|[^>])*?)(\/)?>/g;
  +  let last = 0;
  +  let m: RegExpExecArray | null;
  +
  +  while ((m = re.exec(html))) {
  +    if (m.index > last) {
  +      tokens.push({ kind: "text", text: html.slice(last, m.index) });
  +    }
  +    last = re.lastIndex;
  +    const name = m[2].toLowerCase();
  +    if (m[1]) {
  +      tokens.push({ kind: "close", name });
  +    } else {
  +      tokens.push({
  +        kind: "open",
  +        name,
  +        attrs: parseAttrs(m[3] ?? ""),
  +        void: Boolean(m[4]) || VOID_TAGS.has(name),
  +      });
  +    }
  +  }
  +  if (last < html.length) tokens.push({ kind: "text", text: html.slice(last) });
  +  return tokens;
  +}
  +
  +/** Characters that would otherwise start a Markdown construct. */
  +function escapeInline(text: string): string {
  +  return text.replace(/([\\`*_[\]])/g, "\\$1");
  +}
  +
  +interface Ctx {
  +  /** Inside a table cell: block elements must not emit newlines. */
  +  inCell: boolean;
  +  /** Inside a code block or inline code: no escaping, no marks. */
  +  inCode: boolean;
  +}
  +
  +interface ListFrame {
  +  ordered: boolean;
  +  index: number;
  +  /** Task list items render as `- [ ]` / `- [x]`. */
  +  task: boolean;
  +}
  +
  +/**
  + * Convert an HTML fragment to Markdown.
  + *
  + * GFM is the target: strikethrough, task lists and pipe tables all assume it.
  + * Constructs with no Markdown spelling — superscript, subscript, the endnote
  + * markers — are passed through as inline HTML, which GFM permits and which is
  + * strictly better than dropping them.
  + */
  +export function htmlToMarkdown(html: string): string {
  +  const tokens = tokenize(html);
  +  const out: string[] = [];
  +
  +  const listStack: ListFrame[] = [];
  +  const quoteDepth = { value: 0 };
  +  const ctx: Ctx = { inCell: false, inCode: false };
  +
  +  let discardDepth = 0;
  +  let pendingLinkText: string[] | null = null;
  +  let pendingLinkHref = "";
  +  // Table state. Buffered because a GFM table cannot be streamed: the
  +  // alignment row has to be emitted after the header row is complete.
  +  let table: { rows: string[][]; header: boolean } | null = null;
  +  let cell: string[] | null = null;
  +
  +  /** Where text currently goes: a link label, a table cell, or the output. */
  +  const emit = (s: string) => {
  +    if (!s) return;
  +    if (pendingLinkText) pendingLinkText.push(s);
  +    else if (cell) cell.push(s);
  +    else out.push(s);
  +  };
  +
  +  const blockBreak = () => {
  +    if (cell || pendingLinkText) return;
  +    // Collapse runs of blank lines rather than tracking whether one is due.
  +    while (out.length && /^\s*$/.test(out[out.length - 1] ?? "")) out.pop();
  +    if (out.length) out.push("\n\n");
  +  };
  +
  +  const linePrefix = () => {
  +    const quote = "> ".repeat(quoteDepth.value);
  +    if (listStack.length === 0) return quote;
  +    // Nested list items indent by two spaces per level above the first.
  +    return quote + "  ".repeat(listStack.length - 1);
  +  };
  +
  +  for (let i = 0; i < tokens.length; i++) {
  +    const t = tokens[i];
  +
  +    if (t.kind === "open" && DISCARD_TAGS.has(t.name!)) {
  +      discardDepth++;
  +      continue;
  +    }
  +    if (t.kind === "close" && DISCARD_TAGS.has(t.name!)) {
  +      if (discardDepth > 0) discardDepth--;
  +      continue;
  +    }
  +    if (discardDepth > 0) continue;
  +
  +    if (t.kind === "text") {
  +      const raw = decodeEntities(t.text ?? "");
  +      if (ctx.inCode) {
  +        emit(raw);
  +        continue;
  +      }
  +      // Collapse whitespace the way HTML does, so source indentation in the
  +      // stored document does not become Markdown indentation (which is code).
  +      const collapsed = raw.replace(/\s+/g, " ");
  +      if (collapsed.trim() === "" && !/\S/.test(collapsed)) {
  +        // Keep a single separating space between inline elements.
  +        if (collapsed.length > 0) emit(" ");
  +        continue;
  +      }
  +      emit(escapeInline(collapsed));
  +      continue;
  +    }
  +
  +    const name = t.name!;
  +
  +    if (t.kind === "open") {
  +      switch (name) {
  +        case "br":
  +          // Two trailing spaces is the only hard break Markdown has.
  +          emit(cell ? "<br>" : "  \n" + linePrefix());
  +          break;
  +
  +        case "hr":
  +          blockBreak();
  +          out.push(`${linePrefix()}---`);
  +          break;
  +
  +        case "h1": case "h2": case "h3":
  +        case "h4": case "h5": case "h6":
  +          blockBreak();
  +          out.push(`${linePrefix()}${"#".repeat(Number(name[1]))} `);
  +          break;
  +
  +        case "p":
  +          if (cell) break; // a paragraph inside a cell is just its text
  +          if (listStack.length > 0) break; // list items own their spacing
  +          // A blockquote has already opened the line with its own prefix; the
  +          // first paragraph inside it must continue that line rather than
  +          // break to a new one and emit the prefix twice.
  +          if (out.length && out[out.length - 1] === linePrefix()) break;
  +          blockBreak();
  +          out.push(linePrefix());
  +          break;
  +
  +        case "blockquote":
  +          blockBreak();
  +          quoteDepth.value++;
  +          out.push(linePrefix());
  +          break;
  +
  +        case "ul":
  +        case "ol":
  +          if (listStack.length === 0) blockBreak();
  +          listStack.push({
  +            ordered: name === "ol",
  +            index: Number(t.attrs?.start ?? 1),
  +            task: (t.attrs?.["data-type"] ?? "") === "taskList",
  +          });
  +          break;
  +
  +        case "li": {
  +          const frame = listStack[listStack.length - 1];
  +          if (!frame) break;
  +          if (out.length) out.push("\n");
  +          const marker = frame.ordered ? `${frame.index++}. ` : "- ";
  +          let box = "";
  +          if (frame.task) {
  +            const checked = (t.attrs?.["data-checked"] ?? "") === "true";
  +            box = checked ? "[x] " : "[ ] ";
  +          }
  +          out.push(`${linePrefix()}${marker}${box}`);
  +          break;
  +        }
  +
  +        case "pre":
  +          blockBreak();
  +          ctx.inCode = true;
  +          out.push(`${linePrefix()}\`\`\`\n`);
  +          break;
  +
  +        case "code":
  +          // Inside <pre> the fence already opened; a bare <code> is inline.
  +          if (!ctx.inCode) {
  +            ctx.inCode = true;
  +            emit("`");
  +          }
  +          break;
  +
  +        case "strong": case "b":
  +          emit("**");
  +          break;
  +        case "em": case "i":
  +          emit("*");
  +          break;
  +        case "s": case "del": case "strike":
  +          emit("~~");
  +          break;
  +        case "mark":
  +          emit("==");
  +          break;
  +
  +        case "a":
  +          pendingLinkText = [];
  +          pendingLinkHref = t.attrs?.href ?? "";
  +          break;
  +
  +        case "img": {
  +          const alt = t.attrs?.alt ?? "";
  +          const src = t.attrs?.src ?? "";
  +          // A base64 data URI is megabytes of noise in a text file; name it
  +          // rather than paste it.
  +          const href = src.startsWith("data:") ? "embedded-image" : src;
  +          emit(`![${alt}](${href})`);
  +          break;
  +        }
  +
  +        case "table":
  +          blockBreak();
  +          table = { rows: [], header: false };
  +          break;
  +
  +        case "tr":
  +          table?.rows.push([]);
  +          break;
  +
  +        case "th":
  +          if (table) table.header = true;
  +          cell = [];
  +          break;
  +        case "td":
  +          cell = [];
  +          break;
  +
  +        case "sup": case "sub":
  +          // No Markdown spelling. GFM allows inline HTML, and keeping the tag
  +          // is strictly better than silently dropping the character.
  +          emit(`<${name}>`);
  +          break;
  +
  +        case "div":
  +          if (t.attrs?.["data-page-break"] !== undefined) {
  +            // A page break has no Markdown meaning; `---` would be a lie,
  +            // since that is a horizontal rule and the schema already has one.
  +            break;
  +          }
  +          if (!cell && listStack.length === 0) blockBreak();
  +          break;
  +
  +        default:
  +          break;
  +      }
  +      continue;
  +    }
  +
  +    // close
  +    switch (name) {
  +      case "h1": case "h2": case "h3":
  +      case "h4": case "h5": case "h6":
  +        blockBreak();
  +        break;
  +
  +      case "p":
  +        if (!cell && listStack.length === 0) blockBreak();
  +        break;
  +
  +      case "blockquote":
  +        if (quoteDepth.value > 0) quoteDepth.value--;
  +        blockBreak();
  +        break;
  +
  +      case "ul":
  +      case "ol":
  +        listStack.pop();
  +        if (listStack.length === 0) blockBreak();
  +        break;
  +
  +      case "pre":
  +        ctx.inCode = false;
  +        out.push(`\n${linePrefix()}\`\`\``);
  +        blockBreak();
  +        break;
  +
  +      case "code":
  +        if (ctx.inCode && !out.join("").endsWith("```\n")) {
  +          // Inline code only; the <pre> case is handled above.
  +          const insidePre = tokens
  +            .slice(0, i)
  +            .some((x) => x.kind === "open" && x.name === "pre");
  +          if (!insidePre) {
  +            ctx.inCode = false;
  +            emit("`");
  +          }
  +        }
  +        break;
  +
  +      case "strong": case "b":
  +        emit("**");
  +        break;
  +      case "em": case "i":
  +        emit("*");
  +        break;
  +      case "s": case "del": case "strike":
  +        emit("~~");
  +        break;
  +      case "mark":
  +        emit("==");
  +        break;
  +
  +      case "a": {
  +        const label = (pendingLinkText ?? []).join("").trim();
  +        pendingLinkText = null;
  +        if (!label) break;
  +        emit(pendingLinkHref ? `[${label}](${pendingLinkHref})` : label);
  +        pendingLinkHref = "";
  +        break;
  +      }
  +
  +      case "th":
  +      case "td": {
  +        const text = (cell ?? []).join("").trim().replace(/\|/g, "\\|");
  +        cell = null;
  +        const row = table?.rows[table.rows.length - 1];
  +        row?.push(text);
  +        break;
  +      }
  +
  +      case "table": {
  +        if (table && table.rows.length) {
  +          const rows = table.rows.filter((r) => r.length > 0);
  +          const width = Math.max(...rows.map((r) => r.length));
  +          const pad = (r: string[]) =>
  +            `| ${Array.from({ length: width }, (_, c) => r[c] ?? "").join(" | ")} |`;
  +          const lines = [pad(rows[0])];
  +          lines.push(`| ${Array(width).fill("---").join(" | ")} |`);
  +          for (const r of rows.slice(1)) lines.push(pad(r));
  +          out.push(linePrefix() + lines.join(`\n${linePrefix()}`));
  +          blockBreak();
  +        }
  +        table = null;
  +        break;
  +      }
  +
  +      case "sup": case "sub":
  +        emit(`</${name}>`);
  +        break;
  +
  +      default:
  +        break;
  +    }
  +  }
  +
  +  return out
  +    .join("")
  +    .replace(/[ \t]+$/gm, "")
  +    .replace(/\n{3,}/g, "\n\n")
  +    .trim();
  +}

  diff --git a/src/utils/page-setup.test.ts b/src/utils/page-setup.test.ts
  new file mode 100644
  index 0000000..dd46419
  --- /dev/null
  +++ b/src/utils/page-setup.test.ts
  @@ -0,0 +1,110 @@
  +import { describe, expect, test } from "bun:test";
  +import {
  +  DEFAULT_LAYOUT,
  +  PAPER_SIZE_IN,
  +  resolvePageSetup,
  +  type LayoutSettings,
  +} from "../types";
  +import {
  +  formatMargin,
  +  inToPx,
  +  pxToIn,
  +  pxToRem,
  +  remToPx,
  +} from "./css-units";
  +
  +/**
  + * Page setup arrived after pagination did, which means every folio written
  + * before it exists without a single one of these fields. The contract that
  + * matters most here is the boring one: an old document must still open onto
  + * the page its writer expected, not onto a blank default.
  + */
  +describe("resolvePageSetup", () => {
  +  const legacy: LayoutSettings = {
  +    width: "normal",
  +    margin: "normal",
  +    runningHeader: false,
  +    pageNumbers: true,
  +  };
  +
  +  test("a document written before pagination resolves to Letter portrait", () => {
  +    const s = resolvePageSetup(legacy);
  +    expect(s.paper).toBe("letter");
  +    expect(s.orientation).toBe("portrait");
  +    expect(s.pagination).toBe("paginated");
  +    expect(s.marginUnit).toBe("rem");
  +    expect(s.widthIn).toBe(8.5);
  +    expect(s.heightIn).toBe(11);
  +  });
  +
  +  test("landscape swaps the sheet dimensions", () => {
  +    const s = resolvePageSetup({ ...legacy, orientation: "landscape" });
  +    expect(s.widthIn).toBe(11);
  +    expect(s.heightIn).toBe(8.5);
  +  });
  +
  +  test("A4 is 210 x 297 mm", () => {
  +    // The stored inches are the source of truth; check they round-trip to
  +    // the millimetre figures the rest of the world uses for A4.
  +    const s = resolvePageSetup({ ...legacy, paper: "a4" });
  +    expect(s.widthIn * 25.4).toBeCloseTo(210, 1);
  +    expect(s.heightIn * 25.4).toBeCloseTo(297, 1);
  +  });
  +
  +  test("legal is letter-width but taller", () => {
  +    const s = resolvePageSetup({ ...legacy, paper: "legal" });
  +    expect(s.widthIn).toBe(PAPER_SIZE_IN.letter.w);
  +    expect(s.heightIn).toBe(14);
  +  });
  +
  +  test("continuous mode is honoured rather than overridden", () => {
  +    const s = resolvePageSetup({ ...legacy, pagination: "continuous" });
  +    expect(s.pagination).toBe("continuous");
  +  });
  +
  +  test("an unrecognised paper falls back to Letter instead of NaN", () => {
  +    // Defensive: a hand-edited or future-versioned folio must not produce a
  +    // page of undefined height, which would divide the whole engine by zero.
  +    const s = resolvePageSetup({
  +      ...legacy,
  +      paper: "tabloid" as LayoutSettings["paper"],
  +    });
  +    expect(s.widthIn).toBe(8.5);
  +    expect(s.heightIn).toBe(11);
  +  });
  +
  +  test("the default layout resolves to its own declared values", () => {
  +    const s = resolvePageSetup(DEFAULT_LAYOUT);
  +    expect(s.paper).toBe("letter");
  +    expect(s.orientation).toBe("portrait");
  +    expect(s.pagination).toBe("paginated");
  +  });
  +});
  +
  +/**
  + * The unit bridge. If these drift, screen and print drift with them.
  + */
  +describe("css-units", () => {
  +  test("rem and px agree at a 16px root", () => {
  +    expect(remToPx(3)).toBe(48);
  +    expect(pxToRem(48)).toBe(3);
  +  });
  +
  +  test("px and inches agree at the spec-fixed 96/in", () => {
  +    expect(pxToIn(48)).toBe(0.5);
  +    expect(inToPx(8.5)).toBe(816);
  +  });
  +
  +  test("a non-default root font size scales rem but not inches", () => {
  +    // This is the one knowing divergence between screen and print: the
  +    // reader's text scaling moves the margins, while the sheet stays 8.5in.
  +    expect(remToPx(3, 20)).toBe(60);
  +    expect(inToPx(8.5)).toBe(816);
  +  });
  +
  +  test("formatMargin speaks all three units", () => {
  +    expect(formatMargin(3, "rem")).toBe("3.00 rem");
  +    expect(formatMargin(3, "in")).toBe("0.50 in");
  +    expect(formatMargin(3, "mm")).toBe("12.7 mm");
  +  });
  +});

  diff --git a/src/utils/palette.test.ts b/src/utils/palette.test.ts
  new file mode 100644
  index 0000000..4e49460
  --- /dev/null
  +++ b/src/utils/palette.test.ts
  @@ -0,0 +1,134 @@
  +import { describe, expect, test } from "bun:test";
  +import {
  +  contrastRatio,
  +  HIGHLIGHT_SWATCHES,
  +  INK_SWATCHES,
  +  MANUSCRIPT_INK,
  +  TEXT_SWATCHES,
  +  normalizeHex,
  +  parseHex,
  +  readableInkOn,
  +  swatchByHex,
  +  swatchesFor,
  +} from "./palette";
  +
  +describe("the palette is actually a palette", () => {
  +  test("no two ink swatches are the same paint", () => {
  +    // The list this replaced had six entries and four colours: "wine" was
  +    // mustard and "indigo" was cobalt. A picker that offers the same colour
  +    // twice under different names is worse than one with fewer choices.
  +    const hexes = INK_SWATCHES.map((s) => s.hex.toLowerCase());
  +    expect(new Set(hexes).size).toBe(hexes.length);
  +  });
  +
  +  test("no two highlight swatches are the same paint", () => {
  +    const hexes = HIGHLIGHT_SWATCHES.map((s) => s.hex.toLowerCase());
  +    expect(new Set(hexes).size).toBe(hexes.length);
  +  });
  +
  +  test("ids are unique and stable-looking", () => {
  +    for (const list of [INK_SWATCHES, TEXT_SWATCHES, HIGHLIGHT_SWATCHES]) {
  +      const ids = list.map((s) => s.id);
  +      expect(new Set(ids).size).toBe(ids.length);
  +      for (const id of ids) expect(id).toMatch(/^[a-z][a-z0-9-]*$/);
  +    }
  +  });
  +
  +  test("every swatch carries a literal colour, not only a variable", () => {
  +    // A mark styled with var(--color-mustard) renders nothing in an exported
  +    // standalone HTML file. Colour that leaves the app has to be a literal.
  +    for (const s of [...INK_SWATCHES, ...TEXT_SWATCHES, ...HIGHLIGHT_SWATCHES]) {
  +      expect(s.hex).toMatch(/^#[0-9a-f]{6}$/i);
  +      expect(s.cssVar).toMatch(/^var\(--/);
  +    }
  +  });
  +});
  +
  +describe("highlights stay readable", () => {
  +  test("manuscript ink clears WCAG AA on every highlight", () => {
  +    // The whole point of a highlight is that you can still read the sentence.
  +    for (const s of HIGHLIGHT_SWATCHES) {
  +      const ratio = contrastRatio(s.hex, MANUSCRIPT_INK);
  +      expect(ratio).toBeGreaterThanOrEqual(4.5);
  +    }
  +  });
  +
  +  test("every text colour clears WCAG AA against paper", () => {
  +    // This is why the text list exists separately from the ink list: mustard
  +    // scores 2.0:1 on paper and blush 1.7:1. Both are good badges and neither
  +    // is text, and a single palette serving both jobs offers the writer
  +    // colours their readers cannot read.
  +    const paper = "#f4ecd8";
  +    for (const s of TEXT_SWATCHES) {
  +      expect(contrastRatio(s.hex, paper)).toBeGreaterThanOrEqual(4.5);
  +    }
  +  });
  +
  +  test("the ink list still carries the accents that failed as text", () => {
  +    // Losing them entirely would be the wrong fix — they are the persona
  +    // colours, and a chip is not a paragraph.
  +    const ids = INK_SWATCHES.map((s) => s.id);
  +    expect(ids).toContain("mustard");
  +    expect(ids).toContain("blush");
  +  });
  +
  +  test("no text swatch is the same paint as another", () => {
  +    const hexes = TEXT_SWATCHES.map((s) => s.hex.toLowerCase());
  +    expect(new Set(hexes).size).toBe(hexes.length);
  +  });
  +});
  +
  +describe("contrast maths", () => {
  +  test("black on white is the maximum ratio", () => {
  +    expect(contrastRatio("#000000", "#ffffff")).toBeCloseTo(21, 1);
  +  });
  +
  +  test("a colour against itself is 1", () => {
